-- Mission 25 Part 12G: tenant-private scope, change-order and project-delivery observations.
-- This authority records advice only and never changes imported or NorthStar operational records.

CREATE TABLE public.canonical_external_project_outcome_consents (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES public.organizations(id),
 source_key TEXT NOT NULL CHECK(source_key~'^[a-z0-9][a-z0-9._-]{1,63}$'), revision BIGINT NOT NULL CHECK(revision BETWEEN 1 AND 10000), previous_id UUID,
 action TEXT NOT NULL CHECK(action IN ('grant','revoke')), source_consent_id UUID, source_consent_revision BIGINT, source_consent_digest TEXT,
 actor_user_id UUID NOT NULL, membership_id UUID NOT NULL, auth_session_id UUID NOT NULL,
 reason TEXT NOT NULL CHECK(public.canonical_learning_text_valid(reason,2000)), confirmed BOOLEAN NOT NULL CHECK(confirmed),
 confirmation_version TEXT NOT NULL CHECK(confirmation_version='m25-external-project-outcome-consent-v1'),
 request_key_hash TEXT NOT NULL CHECK(request_key_hash~'^[0-9a-f]{64}$'), request_digest TEXT NOT NULL CHECK(request_digest~'^[0-9a-f]{64}$'),
 canonical_digest TEXT NOT NULL CHECK(canonical_digest~'^[0-9a-f]{64}$'), created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(organization_id,source_key,revision), UNIQUE(organization_id,actor_user_id,request_key_hash), UNIQUE(organization_id,source_key,id),
 FOREIGN KEY(organization_id,membership_id) REFERENCES public.organization_memberships(organization_id,id),
 FOREIGN KEY(organization_id,actor_user_id,auth_session_id) REFERENCES public.auth_sessions(organization_id,user_id,id),
 FOREIGN KEY(organization_id,source_key,previous_id) REFERENCES public.canonical_external_project_outcome_consents(organization_id,source_key,id),
 CHECK((revision=1 AND previous_id IS NULL) OR (revision>1 AND previous_id IS NOT NULL)),
 CHECK((action='grant' AND source_consent_id IS NOT NULL AND source_consent_revision BETWEEN 1 AND 10000 AND source_consent_digest~'^[0-9a-f]{64}$')
  OR (action='revoke' AND source_consent_id IS NULL AND source_consent_revision IS NULL AND source_consent_digest IS NULL))
);

CREATE TABLE public.canonical_external_project_outcome_observations (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES public.organizations(id), source_key TEXT NOT NULL CHECK(source_key~'^[a-z0-9][a-z0-9._-]{1,63}$'),
 estimate_id UUID NOT NULL, project_reference TEXT NOT NULL CHECK(length(project_reference) BETWEEN 1 AND 128 AND project_reference~'^[!-~]+$'),
 revision BIGINT NOT NULL CHECK(revision BETWEEN 1 AND 10000), previous_id UUID,
 consent_id UUID NOT NULL, consent_revision BIGINT NOT NULL CHECK(consent_revision BETWEEN 1 AND 10000), consent_digest TEXT NOT NULL CHECK(consent_digest~'^[0-9a-f]{64}$'),
 project_match_id UUID NOT NULL, project_match_revision BIGINT NOT NULL CHECK(project_match_revision BETWEEN 1 AND 10000), project_match_digest TEXT NOT NULL CHECK(project_match_digest~'^[0-9a-f]{64}$'),
 target_digest TEXT NOT NULL CHECK(target_digest~'^[0-9a-f]{64}$'), source_manifest JSONB NOT NULL CHECK(jsonb_typeof(source_manifest)='array'),
 change_order_matches JSONB NOT NULL CHECK(jsonb_typeof(change_order_matches)='array'), source_digest TEXT NOT NULL CHECK(source_digest~'^[0-9a-f]{64}$'), outcomes JSONB NOT NULL,
 actor_user_id UUID NOT NULL, membership_id UUID NOT NULL, auth_session_id UUID NOT NULL,
 reason TEXT NOT NULL CHECK(public.canonical_learning_text_valid(reason,2000)), confirmed BOOLEAN NOT NULL CHECK(confirmed),
 confirmation_version TEXT NOT NULL CHECK(confirmation_version='m25-external-project-outcome-observation-v1'),
 calculation_version TEXT NOT NULL CHECK(calculation_version='m25-external-project-outcome-v1'),
 request_key_hash TEXT NOT NULL CHECK(request_key_hash~'^[0-9a-f]{64}$'), request_digest TEXT NOT NULL CHECK(request_digest~'^[0-9a-f]{64}$'),
 canonical_digest TEXT NOT NULL CHECK(canonical_digest~'^[0-9a-f]{64}$'), created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(organization_id,source_key,estimate_id,project_reference,revision), UNIQUE(organization_id,actor_user_id,request_key_hash), UNIQUE(organization_id,source_key,estimate_id,project_reference,id),
 FOREIGN KEY(organization_id,membership_id) REFERENCES public.organization_memberships(organization_id,id),
 FOREIGN KEY(organization_id,actor_user_id,auth_session_id) REFERENCES public.auth_sessions(organization_id,user_id,id),
 FOREIGN KEY(organization_id,source_key,consent_id) REFERENCES public.canonical_external_project_outcome_consents(organization_id,source_key,id),
 FOREIGN KEY(organization_id,source_key,estimate_id,project_reference,previous_id) REFERENCES public.canonical_external_project_outcome_observations(organization_id,source_key,estimate_id,project_reference,id),
 CHECK((revision=1 AND previous_id IS NULL) OR (revision>1 AND previous_id IS NOT NULL))
);
CREATE INDEX canonical_external_project_outcomes_current_idx ON public.canonical_external_project_outcome_observations(organization_id,source_key,estimate_id,project_reference,revision DESC);

CREATE FUNCTION public.canonical_external_project_outcome_immutable() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN RAISE EXCEPTION 'Project outcome history is immutable' USING ERRCODE='23514'; END $$;
CREATE TRIGGER canonical_external_project_outcome_consents_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON public.canonical_external_project_outcome_consents FOR EACH STATEMENT EXECUTE FUNCTION public.canonical_external_project_outcome_immutable();
CREATE TRIGGER canonical_external_project_outcome_observations_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON public.canonical_external_project_outcome_observations FOR EACH STATEMENT EXECUTE FUNCTION public.canonical_external_project_outcome_immutable();

CREATE FUNCTION public.canonical_external_project_money_claim_valid(value JSONB,signed_value BOOLEAN) RETURNS BOOLEAN LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT jsonb_typeof(value)='object' AND public.canonical_field_evidence_object_keys_exact(value,ARRAY['status','amount','currency','reason'])
 AND ((value->>'status'='unavailable' AND value->'amount'='null'::jsonb AND value->'currency'='null'::jsonb AND jsonb_typeof(value->'reason')='string' AND public.canonical_learning_text_valid(value->>'reason',500))
 OR (value->>'status'='recorded' AND jsonb_typeof(value->'amount')='string' AND ((signed_value AND value->>'amount'~'^-?(0|[1-9][0-9]{0,14})(\.[0-9]{1,6})?$') OR (NOT signed_value AND value->>'amount'~'^(0|[1-9][0-9]{0,14})(\.[0-9]{1,6})?$')) AND jsonb_typeof(value->'currency')='string' AND value->>'currency'~'^[A-Z]{3}$' AND value->'reason'='null'::jsonb)) $$;

CREATE FUNCTION public.canonical_external_project_outcomes_valid(value JSONB) RETURNS BOOLEAN LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT jsonb_typeof(value)='object' AND public.canonical_field_evidence_object_keys_exact(value,ARRAY['scope','changeOrders','projectDelivery'])
 AND jsonb_typeof(value->'scope')='object' AND public.canonical_field_evidence_object_keys_exact(value->'scope',ARRAY['status','originalContract','currentContract','contractChange','reason'])
 AND ((value->'scope'->>'status'='unavailable' AND value->'scope'->'originalContract'='null'::jsonb AND value->'scope'->'currentContract'='null'::jsonb AND value->'scope'->'contractChange'='null'::jsonb AND jsonb_typeof(value->'scope'->'reason')='string' AND public.canonical_learning_text_valid(value->'scope'->>'reason',500))
  OR (value->'scope'->>'status'='recorded' AND public.canonical_external_project_money_claim_valid(value->'scope'->'originalContract',FALSE) AND public.canonical_external_project_money_claim_valid(value->'scope'->'currentContract',FALSE) AND public.canonical_external_project_money_claim_valid(value->'scope'->'contractChange',TRUE) AND value->'scope'->'reason'='null'::jsonb))
 AND jsonb_typeof(value->'changeOrders')='object' AND public.canonical_field_evidence_object_keys_exact(value->'changeOrders',ARRAY['status','recordCount','states','signedValue','reason'])
 AND ((value->'changeOrders'->>'status'='unavailable' AND value->'changeOrders'->'recordCount'='null'::jsonb AND value->'changeOrders'->'states'='null'::jsonb AND value->'changeOrders'->'signedValue'='null'::jsonb AND jsonb_typeof(value->'changeOrders'->'reason')='string' AND public.canonical_learning_text_valid(value->'changeOrders'->>'reason',500))
  OR (value->'changeOrders'->>'status'='recorded' AND jsonb_typeof(value->'changeOrders'->'recordCount')='number' AND (value->'changeOrders'->>'recordCount')~'^[1-9][0-9]{0,5}$' AND jsonb_typeof(value->'changeOrders'->'states')='object' AND public.canonical_field_evidence_object_keys_exact(value->'changeOrders'->'states',ARRAY['proposed','approved','rejected','voided','completed','unknown']) AND NOT EXISTS(SELECT 1 FROM jsonb_each(value->'changeOrders'->'states')s WHERE jsonb_typeof(s.value)<>'number' OR s.value#>>'{}'!~'^(0|[1-9][0-9]{0,5})$') AND public.canonical_external_project_money_claim_valid(value->'changeOrders'->'signedValue',TRUE) AND value->'changeOrders'->'reason'='null'::jsonb))
 AND jsonb_typeof(value->'projectDelivery')='object' AND public.canonical_field_evidence_object_keys_exact(value->'projectDelivery',ARRAY['status','state','occurredAt','endedAt','durationSeconds','reason'])
 AND ((value->'projectDelivery'->>'status'='unavailable' AND value->'projectDelivery'->'state'='null'::jsonb AND value->'projectDelivery'->'occurredAt'='null'::jsonb AND value->'projectDelivery'->'endedAt'='null'::jsonb AND value->'projectDelivery'->'durationSeconds'='null'::jsonb AND jsonb_typeof(value->'projectDelivery'->'reason')='string' AND public.canonical_learning_text_valid(value->'projectDelivery'->>'reason',500))
  OR (value->'projectDelivery'->>'status'='recorded' AND value->'projectDelivery'->>'state' IN ('proposed','active','on_hold','completed','canceled','unknown') AND jsonb_typeof(value->'projectDelivery'->'occurredAt')='string' AND pg_input_is_valid(value->'projectDelivery'->>'occurredAt','timestamp with time zone') AND (value->'projectDelivery'->'endedAt'='null'::jsonb OR (jsonb_typeof(value->'projectDelivery'->'endedAt')='string' AND pg_input_is_valid(value->'projectDelivery'->>'endedAt','timestamp with time zone'))) AND ((value->'projectDelivery'->'endedAt'='null'::jsonb AND value->'projectDelivery'->'durationSeconds'='null'::jsonb) OR (jsonb_typeof(value->'projectDelivery'->'durationSeconds')='string' AND value->'projectDelivery'->>'durationSeconds'~'^(0|[1-9][0-9]{0,15})(\.[0-9]{1,6})?$')) AND value->'projectDelivery'->'reason'='null'::jsonb)) $$;
ALTER TABLE public.canonical_external_project_outcome_observations ADD CONSTRAINT canonical_external_project_outcomes_valid_check CHECK(public.canonical_external_project_outcomes_valid(outcomes));

CREATE FUNCTION public.canonical_external_project_outcome_unavailable(reason_value TEXT) RETURNS JSONB LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT jsonb_build_object('scope',jsonb_build_object('status','unavailable','originalContract',NULL,'currentContract',NULL,'contractChange',NULL,'reason',reason_value),'changeOrders',jsonb_build_object('status','unavailable','recordCount',NULL,'states',NULL,'signedValue',NULL,'reason',reason_value),'projectDelivery',jsonb_build_object('status','unavailable','state',NULL,'occurredAt',NULL,'endedAt',NULL,'durationSeconds',NULL,'reason',reason_value)) $$;

CREATE FUNCTION public.canonical_external_project_outcome_consent_projection(value public.canonical_external_project_outcome_consents,source_current JSONB) RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT jsonb_build_object('id',value.id,'sourceKey',value.source_key,'revision',value.revision,'previousId',value.previous_id,'action',value.action,'sourcePermissionCurrent',COALESCE(value.action='grant' AND source_current->>'id'=value.source_consent_id::text AND source_current->>'digest'=rtrim(value.source_consent_digest),FALSE),'reason',value.reason,'confirmed',value.confirmed,'confirmationVersion',value.confirmation_version,'digest',rtrim(value.canonical_digest),'createdAt',value.created_at) $$;

CREATE FUNCTION public.canonical_external_project_outcome_consent_guard() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE source_current JSONB;previous_row public.canonical_external_project_outcome_consents%ROWTYPE;expected_digest TEXT;
BEGIN source_current:=public.canonical_external_business_source_consent_basis(NEW.organization_id,'project_change_order',NEW.source_key);IF NEW.action='grant' AND (source_current IS NULL OR NEW.source_consent_id<>(source_current->>'id')::uuid OR NEW.source_consent_revision<>(source_current->>'revision')::bigint OR rtrim(NEW.source_consent_digest)<>source_current->>'digest') THEN RAISE EXCEPTION 'Project outcome source permission invalid' USING ERRCODE='23514';END IF;IF NEW.revision>1 THEN SELECT * INTO previous_row FROM public.canonical_external_project_outcome_consents WHERE organization_id=NEW.organization_id AND source_key=NEW.source_key AND id=NEW.previous_id;IF previous_row.id IS NULL OR previous_row.revision+1<>NEW.revision THEN RAISE EXCEPTION 'Project outcome permission revision invalid' USING ERRCODE='23514';END IF;END IF;expected_digest:=public.canonical_completion_digest(jsonb_build_object('organizationId',NEW.organization_id,'sourceKey',NEW.source_key,'revision',NEW.revision,'previousId',NEW.previous_id,'action',NEW.action,'sourceConsentId',NEW.source_consent_id,'sourceConsentRevision',NEW.source_consent_revision,'sourceConsentDigest',rtrim(NEW.source_consent_digest),'actorUserId',NEW.actor_user_id,'reason',NEW.reason,'confirmationVersion',NEW.confirmation_version,'requestDigest',rtrim(NEW.request_digest)));IF rtrim(NEW.canonical_digest)<>expected_digest THEN RAISE EXCEPTION 'Project outcome permission digest invalid' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER canonical_external_project_outcome_consent_guard BEFORE INSERT ON public.canonical_external_project_outcome_consents FOR EACH ROW EXECUTE FUNCTION public.canonical_external_project_outcome_consent_guard();

CREATE FUNCTION public.canonical_external_project_outcome_basis(org UUID,source_value TEXT,estimate_value UUID,project_reference_value TEXT) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE source_consent JSONB;source_basis RECORD;project_match public.canonical_external_business_reference_matches%ROWTYPE;target_basis JSONB;project_record public.canonical_external_project_change_order_import_records%ROWTYPE;project_total BIGINT;change_total BIGINT;duplicate_total BIGINT;unmatched_total BIGINT;change_matches JSONB;scope_value JSONB;change_value JSONB;delivery_value JSONB;original_claim JSONB;current_claim JSONB;difference_claim JSONB;signed_claim JSONB;currency_total BIGINT;value_total BIGINT;signed_total NUMERIC;digest_value TEXT;
BEGIN source_consent:=public.canonical_external_business_source_consent_basis(org,'project_change_order',source_value);IF source_consent IS NULL THEN RETURN NULL;END IF;SELECT * INTO source_basis FROM public.canonical_external_business_source_references(org,'project_change_order',source_value)s WHERE s.reference_kind='project' AND s.external_reference=project_reference_value;IF source_basis.source_digest IS NULL THEN RETURN NULL;END IF;SELECT * INTO project_match FROM public.canonical_external_business_reference_matches WHERE organization_id=org AND source_class='project_change_order' AND source_key=source_value AND consent_id=(source_consent->>'id')::uuid AND reference_kind='project' AND external_reference=project_reference_value ORDER BY revision DESC LIMIT 1;target_basis:=public.canonical_external_business_reference_target_basis(org,'project',estimate_value);IF target_basis IS NULL OR project_match.id IS NULL OR project_match.action<>'link' OR project_match.target_id<>estimate_value OR project_match.source_digest<>source_basis.source_digest OR project_match.target_digest<>target_basis->>'digest' THEN RETURN NULL;END IF;
 WITH current_records AS MATERIALIZED(SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_project_change_order_import_records r WHERE r.organization_id=org AND r.source_key=source_value AND r.consent_id=(source_consent->>'id')::uuid ORDER BY r.external_record_id,r.revision DESC),relevant AS(SELECT * FROM current_records WHERE state='active' AND project_reference=project_reference_value)
 SELECT count(*) FILTER(WHERE record_type='project') INTO project_total FROM relevant;
 WITH current_records AS(SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_project_change_order_import_records r WHERE r.organization_id=org AND r.source_key=source_value AND r.consent_id=(source_consent->>'id')::uuid ORDER BY r.external_record_id,r.revision DESC) SELECT * INTO project_record FROM current_records WHERE state='active' AND record_type='project' AND project_reference=project_reference_value ORDER BY external_record_id LIMIT 1;
 WITH current_records AS MATERIALIZED(SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_project_change_order_import_records r WHERE r.organization_id=org AND r.source_key=source_value AND r.consent_id=(source_consent->>'id')::uuid ORDER BY r.external_record_id,r.revision DESC),refs AS(SELECT change_order_reference,count(*) record_count FROM current_records WHERE state='active' AND record_type='change_order' AND project_reference=project_reference_value GROUP BY change_order_reference),details AS(SELECT refs.*,s.source_digest,m.id match_id,m.revision match_revision,rtrim(m.canonical_digest) match_digest,m.action,m.target_id,m.source_digest match_source_digest,m.target_digest match_target_digest FROM refs LEFT JOIN LATERAL(SELECT * FROM public.canonical_external_business_source_references(org,'project_change_order',source_value)x WHERE x.reference_kind='change_order' AND x.external_reference=refs.change_order_reference)s ON TRUE LEFT JOIN LATERAL(SELECT * FROM public.canonical_external_business_reference_matches x WHERE x.organization_id=org AND x.source_class='project_change_order' AND x.source_key=source_value AND x.consent_id=(source_consent->>'id')::uuid AND x.reference_kind='change_order' AND x.external_reference=refs.change_order_reference ORDER BY x.revision DESC LIMIT 1)m ON TRUE)
 SELECT count(*),count(*)FILTER(WHERE record_count<>1),count(*)FILTER(WHERE source_digest IS NULL OR match_id IS NULL OR action IS DISTINCT FROM 'link' OR target_id IS DISTINCT FROM estimate_value OR match_source_digest IS DISTINCT FROM source_digest OR match_target_digest IS DISTINCT FROM target_basis->>'digest'),COALESCE(jsonb_agg(jsonb_build_object('changeOrderReference',change_order_reference,'sourceDigest',source_digest,'recordCount',record_count,'matchId',match_id,'matchRevision',match_revision,'matchDigest',match_digest,'current',COALESCE(source_digest IS NOT NULL AND match_id IS NOT NULL AND action='link' AND target_id=estimate_value AND match_source_digest=source_digest AND match_target_digest=target_basis->>'digest',FALSE))ORDER BY change_order_reference),'[]'::jsonb) INTO change_total,duplicate_total,unmatched_total,change_matches FROM details;
 IF project_total=1 THEN original_claim:=CASE WHEN project_record.original_contract->>'status'='recorded' THEN jsonb_build_object('status','recorded','amount',project_record.original_contract->>'amount','currency',project_record.original_contract->>'currency','reason',NULL) ELSE jsonb_build_object('status','unavailable','amount',NULL,'currency',NULL,'reason','The original contract value is unavailable in the current project record.') END;current_claim:=CASE WHEN project_record.current_contract->>'status'='recorded' THEN jsonb_build_object('status','recorded','amount',project_record.current_contract->>'amount','currency',project_record.current_contract->>'currency','reason',NULL) ELSE jsonb_build_object('status','unavailable','amount',NULL,'currency',NULL,'reason','The current contract value is unavailable in the current project record.') END;difference_claim:=CASE WHEN project_record.original_contract->>'status'='recorded' AND project_record.current_contract->>'status'='recorded' AND project_record.original_contract->>'currency'=project_record.current_contract->>'currency' THEN jsonb_build_object('status','recorded','amount',trim_scale((project_record.current_contract->>'amount')::numeric-(project_record.original_contract->>'amount')::numeric)::text,'currency',project_record.current_contract->>'currency','reason',NULL) ELSE jsonb_build_object('status','unavailable','amount',NULL,'currency',NULL,'reason','Comparable original and current contract values in one currency are required.') END;scope_value:=jsonb_build_object('status','recorded','originalContract',original_claim,'currentContract',current_claim,'contractChange',difference_claim,'reason',NULL);delivery_value:=jsonb_build_object('status','recorded','state',project_record.record_state,'occurredAt',project_record.occurred_at,'endedAt',project_record.ended_at,'durationSeconds',CASE WHEN project_record.ended_at IS NULL THEN NULL ELSE trim_scale(extract(epoch FROM project_record.ended_at-project_record.occurred_at))::text END,'reason',NULL);ELSE scope_value:=jsonb_build_object('status','unavailable','originalContract',NULL,'currentContract',NULL,'contractChange',NULL,'reason',CASE WHEN project_total=0 THEN 'No current project record is available for this reviewed project.' ELSE 'More than one current project record needs source review.' END);delivery_value:=jsonb_build_object('status','unavailable','state',NULL,'occurredAt',NULL,'endedAt',NULL,'durationSeconds',NULL,'reason',CASE WHEN project_total=0 THEN 'No current project delivery record is available.' ELSE 'More than one current project delivery record needs source review.' END);END IF;
 IF change_total=0 THEN change_value:=jsonb_build_object('status','unavailable','recordCount',NULL,'states',NULL,'signedValue',NULL,'reason','No current change-order record is available for this reviewed project.');ELSIF duplicate_total>0 THEN change_value:=jsonb_build_object('status','unavailable','recordCount',NULL,'states',NULL,'signedValue',NULL,'reason','A change order has more than one current record and needs source review.');ELSIF unmatched_total>0 THEN change_value:=jsonb_build_object('status','unavailable','recordCount',NULL,'states',NULL,'signedValue',NULL,'reason','Every current change order must be reviewed against this NorthStar estimate.');ELSE WITH current_records AS(SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_project_change_order_import_records r WHERE r.organization_id=org AND r.source_key=source_value AND r.consent_id=(source_consent->>'id')::uuid ORDER BY r.external_record_id,r.revision DESC),relevant AS(SELECT * FROM current_records WHERE state='active' AND record_type='change_order' AND project_reference=project_reference_value) SELECT count(*)FILTER(WHERE change_order_value->>'status'='recorded'),count(DISTINCT change_order_value->>'currency')FILTER(WHERE change_order_value->>'status'='recorded'),COALESCE(sum(CASE change_order_value->>'effect' WHEN 'increase' THEN (change_order_value->>'amount')::numeric WHEN 'decrease' THEN -(change_order_value->>'amount')::numeric ELSE 0 END)FILTER(WHERE change_order_value->>'status'='recorded'),0) INTO value_total,currency_total,signed_total FROM relevant;signed_claim:=CASE WHEN value_total=change_total AND currency_total=1 THEN (WITH current_records AS(SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_project_change_order_import_records r WHERE r.organization_id=org AND r.source_key=source_value AND r.consent_id=(source_consent->>'id')::uuid ORDER BY r.external_record_id,r.revision DESC)SELECT jsonb_build_object('status','recorded','amount',trim_scale(signed_total)::text,'currency',min(change_order_value->>'currency'),'reason',NULL) FROM current_records WHERE state='active' AND record_type='change_order' AND project_reference=project_reference_value) ELSE jsonb_build_object('status','unavailable','amount',NULL,'currency',NULL,'reason','Every current change order needs a recorded value in one currency before a signed total is available.') END;WITH current_records AS(SELECT DISTINCT ON(r.external_record_id)r.* FROM public.canonical_external_project_change_order_import_records r WHERE r.organization_id=org AND r.source_key=source_value AND r.consent_id=(source_consent->>'id')::uuid ORDER BY r.external_record_id,r.revision DESC),relevant AS(SELECT * FROM current_records WHERE state='active' AND record_type='change_order' AND project_reference=project_reference_value) SELECT jsonb_build_object('status','recorded','recordCount',count(*),'states',jsonb_build_object('proposed',count(*)FILTER(WHERE record_state='proposed'),'approved',count(*)FILTER(WHERE record_state='approved'),'rejected',count(*)FILTER(WHERE record_state='rejected'),'voided',count(*)FILTER(WHERE record_state='voided'),'completed',count(*)FILTER(WHERE record_state='completed'),'unknown',count(*)FILTER(WHERE record_state='unknown')),'signedValue',signed_claim,'reason',NULL) INTO change_value FROM relevant;END IF;
 digest_value:=public.canonical_completion_digest(jsonb_build_object('organizationId',org,'sourceKey',source_value,'sourceConsent',source_consent,'estimateId',estimate_value,'projectReference',project_reference_value,'projectMatchId',project_match.id,'projectMatchDigest',rtrim(project_match.canonical_digest),'targetDigest',target_basis->>'digest','sourceManifest',source_basis.manifest,'changeOrderMatches',change_matches,'outcomes',jsonb_build_object('scope',scope_value,'changeOrders',change_value,'projectDelivery',delivery_value)));
 RETURN jsonb_build_object('sourceConsent',source_consent,'projectMatchId',project_match.id,'projectMatchRevision',project_match.revision,'projectMatchDigest',rtrim(project_match.canonical_digest),'targetDigest',target_basis->>'digest','sourceManifest',source_basis.manifest,'changeOrderMatches',change_matches,'outcomes',jsonb_build_object('scope',scope_value,'changeOrders',change_value,'projectDelivery',delivery_value),'sourceDigest',digest_value);END $$;

CREATE FUNCTION public.canonical_external_project_outcome_consent_read(org UUID,actor UUID,role_value TEXT,session_value UUID,source_value TEXT) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ DECLARE row_value public.canonical_external_project_outcome_consents%ROWTYPE;source_current JSONB;BEGIN IF role_value IS NULL OR role_value NOT IN ('owner','admin') THEN RAISE EXCEPTION 'Project outcome learning restricted' USING ERRCODE='42501';END IF;PERFORM public.canonical_field_execution_actor_authority(org,actor,role_value,session_value,NULL,FALSE);IF source_value IS NULL OR source_value!~'^[a-z0-9][a-z0-9._-]{1,63}$' THEN RAISE EXCEPTION 'Project outcome permission read invalid' USING ERRCODE='22023';END IF;source_current:=public.canonical_external_business_source_consent_basis(org,'project_change_order',source_value);SELECT * INTO row_value FROM public.canonical_external_project_outcome_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1;RETURN jsonb_build_object('sourceKey',source_value,'current',CASE WHEN row_value.id IS NULL THEN NULL ELSE public.canonical_external_project_outcome_consent_projection(row_value,source_current)END,'sourcePermissionAvailable',source_current IS NOT NULL,'consumptionBoundary','Project outcome learning records advice only and changes no project, change order, estimate, schedule, price or policy.');END $$;

CREATE FUNCTION public.canonical_external_project_outcome_consent_mutate(org UUID,actor UUID,role_value TEXT,session_value UUID,csrf TEXT,key_value TEXT,source_value TEXT,body JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE authority JSONB;current_row public.canonical_external_project_outcome_consents%ROWTYPE;replay public.canonical_external_project_outcome_consents%ROWTYPE;inserted public.canonical_external_project_outcome_consents%ROWTYPE;source_current JSONB;key_hash TEXT;request_hash TEXT;digest_value TEXT;next_revision BIGINT;
BEGIN IF current_setting('transaction_isolation')<>'serializable' THEN RAISE EXCEPTION 'Serializable required' USING ERRCODE='25001';END IF;IF role_value IS NULL OR role_value NOT IN ('owner','admin') THEN RAISE EXCEPTION 'Project outcome learning restricted' USING ERRCODE='42501';END IF;PERFORM 1 FROM public.subscriptions WHERE organization_id=org FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Subscription unavailable' USING ERRCODE='42501';END IF;authority:=public.canonical_field_execution_actor_authority(org,actor,role_value,session_value,csrf,TRUE);IF source_value IS NULL OR source_value!~'^[a-z0-9][a-z0-9._-]{1,63}$' OR key_value IS NULL OR key_value!~'^[A-Za-z0-9._:-]{16,128}$' OR octet_length(body::text)>8192 OR public.canonical_field_evidence_object_keys_exact(body,ARRAY['action','expectedRevision','expectedDigest','reason','confirmed','confirmationVersion']) IS NOT TRUE OR body->>'action' NOT IN ('grant','revoke') OR jsonb_typeof(body->'expectedRevision')<>'number' OR (body->>'expectedRevision')!~'^(0|[1-9][0-9]{0,3}|10000)$' OR body->>'expectedDigest'!~'^(none|[0-9a-f]{64})$' OR (((body->>'expectedRevision')::bigint=0)<>(body->>'expectedDigest'='none')) OR public.canonical_learning_text_valid(body->>'reason',2000) IS NOT TRUE OR body->'confirmed' IS DISTINCT FROM 'true'::jsonb OR body->>'confirmationVersion'<>'m25-external-project-outcome-consent-v1' THEN RAISE EXCEPTION 'Project outcome permission invalid' USING ERRCODE='22023';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(org::text||':external-project-outcome:'||source_value,0));key_hash:=encode(sha256(convert_to(key_value,'UTF8')),'hex');request_hash:=public.canonical_completion_digest(jsonb_build_object('organizationId',org,'actorUserId',actor,'sourceKey',source_value,'body',body));SELECT * INTO replay FROM public.canonical_external_project_outcome_consents WHERE organization_id=org AND actor_user_id=actor AND request_key_hash=key_hash;IF FOUND THEN IF rtrim(replay.request_digest)<>request_hash THEN RAISE EXCEPTION 'Project outcome permission key conflict' USING ERRCODE='23505';END IF;source_current:=public.canonical_external_business_source_consent_basis(org,'project_change_order',source_value);RETURN jsonb_build_object('consent',public.canonical_external_project_outcome_consent_projection(replay,source_current),'replayed',TRUE);END IF;SELECT * INTO current_row FROM public.canonical_external_project_outcome_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1 FOR UPDATE;IF (body->>'expectedRevision')::bigint<>COALESCE(current_row.revision,0) OR body->>'expectedDigest'<>COALESCE(rtrim(current_row.canonical_digest),'none') THEN RAISE EXCEPTION 'Project outcome permission changed' USING ERRCODE='40001';END IF;source_current:=public.canonical_external_business_source_consent_basis(org,'project_change_order',source_value);IF body->>'action'='grant' AND source_current IS NULL THEN RAISE EXCEPTION 'Current project source permission required' USING ERRCODE='P0002',CONSTRAINT='project_outcome_consent_unavailable';END IF;next_revision:=COALESCE(current_row.revision,0)+1;digest_value:=public.canonical_completion_digest(jsonb_build_object('organizationId',org,'sourceKey',source_value,'revision',next_revision,'previousId',current_row.id,'action',body->>'action','sourceConsentId',CASE WHEN body->>'action'='grant' THEN source_current->>'id' END,'sourceConsentRevision',CASE WHEN body->>'action'='grant' THEN (source_current->>'revision')::bigint END,'sourceConsentDigest',CASE WHEN body->>'action'='grant' THEN source_current->>'digest' END,'actorUserId',actor,'reason',body->>'reason','confirmationVersion',body->>'confirmationVersion','requestDigest',request_hash));INSERT INTO public.canonical_external_project_outcome_consents(organization_id,source_key,revision,previous_id,action,source_consent_id,source_consent_revision,source_consent_digest,actor_user_id,membership_id,auth_session_id,reason,confirmed,confirmation_version,request_key_hash,request_digest,canonical_digest)VALUES(org,source_value,next_revision,current_row.id,body->>'action',CASE WHEN body->>'action'='grant' THEN (source_current->>'id')::uuid END,CASE WHEN body->>'action'='grant' THEN (source_current->>'revision')::bigint END,CASE WHEN body->>'action'='grant' THEN source_current->>'digest' END,actor,(authority->>'membershipId')::uuid,session_value,body->>'reason',TRUE,body->>'confirmationVersion',key_hash,request_hash,digest_value)RETURNING * INTO inserted;RETURN jsonb_build_object('consent',public.canonical_external_project_outcome_consent_projection(inserted,source_current),'replayed',FALSE);END $$;

CREATE FUNCTION public.canonical_external_project_outcome_projection(value public.canonical_external_project_outcome_observations,basis JSONB,consent_value public.canonical_external_project_outcome_consents,source_current JSONB) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ DECLARE active_value BOOLEAN;fresh_value BOOLEAN;BEGIN active_value:=COALESCE(consent_value.id=value.consent_id AND consent_value.action='grant' AND source_current->>'id'=consent_value.source_consent_id::text AND source_current->>'digest'=rtrim(consent_value.source_consent_digest),FALSE);IF NOT active_value THEN RETURN jsonb_build_object('id',value.id,'revision',value.revision,'fresh',FALSE,'hiddenByConsent',TRUE,'advisoryAvailable',FALSE,'refreshRequired',TRUE,'outcomes',public.canonical_external_project_outcome_unavailable('Project outcome advice is hidden because permission is inactive.'),'digest',rtrim(value.canonical_digest),'createdAt',value.created_at);END IF;fresh_value:=basis IS NOT NULL AND basis->>'sourceDigest'=value.source_digest;RETURN jsonb_build_object('id',value.id,'sourceKey',value.source_key,'estimateId',value.estimate_id,'projectReference',value.project_reference,'revision',value.revision,'previousId',value.previous_id,'consentId',value.consent_id,'consentRevision',value.consent_revision,'consentDigest',rtrim(value.consent_digest),'projectMatchId',value.project_match_id,'projectMatchRevision',value.project_match_revision,'projectMatchDigest',rtrim(value.project_match_digest),'targetDigest',rtrim(value.target_digest),'sourceManifest',value.source_manifest,'changeOrderMatches',value.change_order_matches,'sourceDigest',rtrim(value.source_digest),'outcomes',CASE WHEN fresh_value THEN value.outcomes ELSE public.canonical_external_project_outcome_unavailable('Current evidence or reviewed links changed. Refresh before using this advice.')END,'fresh',fresh_value,'hiddenByConsent',FALSE,'advisoryAvailable',fresh_value,'refreshRequired',NOT fresh_value,'reason',value.reason,'confirmed',value.confirmed,'confirmationVersion',value.confirmation_version,'calculationVersion',value.calculation_version,'digest',rtrim(value.canonical_digest),'createdAt',value.created_at,'adoptionBoundary','No project, change order, customer, job, estimate, schedule, price, financial record, source record or company policy was changed.');END $$;

CREATE FUNCTION public.canonical_external_project_outcome_observation_guard() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ DECLARE basis JSONB;consent_value public.canonical_external_project_outcome_consents%ROWTYPE;source_current JSONB;previous_row public.canonical_external_project_outcome_observations%ROWTYPE;expected_digest TEXT;BEGIN SELECT * INTO consent_value FROM public.canonical_external_project_outcome_consents WHERE id=NEW.consent_id AND organization_id=NEW.organization_id;source_current:=public.canonical_external_business_source_consent_basis(NEW.organization_id,'project_change_order',NEW.source_key);basis:=public.canonical_external_project_outcome_basis(NEW.organization_id,NEW.source_key,NEW.estimate_id,NEW.project_reference);IF consent_value.id IS NULL OR consent_value.action<>'grant' OR consent_value.revision<>NEW.consent_revision OR rtrim(consent_value.canonical_digest)<>rtrim(NEW.consent_digest) OR source_current IS NULL OR consent_value.source_consent_id<>(source_current->>'id')::uuid OR consent_value.source_consent_revision<>(source_current->>'revision')::bigint OR rtrim(consent_value.source_consent_digest)<>source_current->>'digest' OR basis IS NULL OR basis->>'sourceDigest'<>NEW.source_digest OR basis->'outcomes'<>NEW.outcomes OR basis->'sourceManifest'<>NEW.source_manifest OR basis->'changeOrderMatches'<>NEW.change_order_matches OR (basis->>'projectMatchId')::uuid<>NEW.project_match_id OR (basis->>'projectMatchRevision')::bigint<>NEW.project_match_revision OR basis->>'projectMatchDigest'<>rtrim(NEW.project_match_digest) OR basis->>'targetDigest'<>rtrim(NEW.target_digest) THEN RAISE EXCEPTION 'Project outcome lineage invalid' USING ERRCODE='23514';END IF;IF NEW.revision>1 THEN SELECT * INTO previous_row FROM public.canonical_external_project_outcome_observations WHERE organization_id=NEW.organization_id AND source_key=NEW.source_key AND estimate_id=NEW.estimate_id AND project_reference=NEW.project_reference AND id=NEW.previous_id;IF previous_row.id IS NULL OR previous_row.revision+1<>NEW.revision THEN RAISE EXCEPTION 'Project outcome observation revision invalid' USING ERRCODE='23514';END IF;END IF;expected_digest:=public.canonical_completion_digest(jsonb_build_object('organizationId',NEW.organization_id,'sourceKey',NEW.source_key,'estimateId',NEW.estimate_id,'projectReference',NEW.project_reference,'revision',NEW.revision,'previousId',NEW.previous_id,'consentId',NEW.consent_id,'consentRevision',NEW.consent_revision,'consentDigest',rtrim(NEW.consent_digest),'projectMatchId',NEW.project_match_id,'projectMatchRevision',NEW.project_match_revision,'projectMatchDigest',rtrim(NEW.project_match_digest),'targetDigest',rtrim(NEW.target_digest),'sourceManifest',NEW.source_manifest,'changeOrderMatches',NEW.change_order_matches,'sourceDigest',NEW.source_digest,'outcomes',NEW.outcomes,'actorUserId',NEW.actor_user_id,'confirmationVersion',NEW.confirmation_version,'calculationVersion',NEW.calculation_version,'requestDigest',rtrim(NEW.request_digest)));IF rtrim(NEW.canonical_digest)<>expected_digest THEN RAISE EXCEPTION 'Project outcome observation digest invalid' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER canonical_external_project_outcome_observation_guard BEFORE INSERT ON public.canonical_external_project_outcome_observations FOR EACH ROW EXECUTE FUNCTION public.canonical_external_project_outcome_observation_guard();

CREATE FUNCTION public.canonical_external_project_outcome_observe(org UUID,actor UUID,role_value TEXT,session_value UUID,csrf TEXT,key_value TEXT,source_value TEXT,estimate_value UUID,project_reference_value TEXT,expected_consent_revision BIGINT,expected_consent_digest TEXT,reason_value TEXT,confirmed_value BOOLEAN,confirmation_version_value TEXT) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE authority JSONB;consent_value public.canonical_external_project_outcome_consents%ROWTYPE;current_row public.canonical_external_project_outcome_observations%ROWTYPE;replay public.canonical_external_project_outcome_observations%ROWTYPE;inserted public.canonical_external_project_outcome_observations%ROWTYPE;source_current JSONB;basis JSONB;key_hash TEXT;request_hash TEXT;digest_value TEXT;next_revision BIGINT;
BEGIN IF current_setting('transaction_isolation')<>'serializable' THEN RAISE EXCEPTION 'Serializable required' USING ERRCODE='25001';END IF;IF role_value IS NULL OR role_value NOT IN ('owner','admin') THEN RAISE EXCEPTION 'Project outcome learning restricted' USING ERRCODE='42501';END IF;PERFORM 1 FROM public.subscriptions WHERE organization_id=org FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Subscription unavailable' USING ERRCODE='42501';END IF;authority:=public.canonical_field_execution_actor_authority(org,actor,role_value,session_value,csrf,TRUE);IF source_value IS NULL OR source_value!~'^[a-z0-9][a-z0-9._-]{1,63}$' OR project_reference_value IS NULL OR length(project_reference_value) NOT BETWEEN 1 AND 128 OR project_reference_value!~'^[!-~]+$' OR key_value IS NULL OR key_value!~'^[A-Za-z0-9._:-]{16,128}$' OR expected_consent_revision NOT BETWEEN 1 AND 10000 OR expected_consent_digest!~'^[0-9a-f]{64}$' OR public.canonical_learning_text_valid(reason_value,2000) IS NOT TRUE OR confirmed_value IS DISTINCT FROM TRUE OR confirmation_version_value<>'m25-external-project-outcome-observation-v1' THEN RAISE EXCEPTION 'Project outcome observation invalid' USING ERRCODE='22023';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(org::text||':external-project-outcome:'||source_value,0));PERFORM pg_advisory_xact_lock(hashtextextended(org::text||':external-project-outcome-observation:'||estimate_value::text||':'||project_reference_value,0));key_hash:=encode(sha256(convert_to(key_value,'UTF8')),'hex');request_hash:=public.canonical_completion_digest(jsonb_build_object('organizationId',org,'actorUserId',actor,'sourceKey',source_value,'estimateId',estimate_value,'projectReference',project_reference_value,'expectedConsentRevision',expected_consent_revision,'expectedConsentDigest',expected_consent_digest,'reason',reason_value,'confirmed',confirmed_value,'confirmationVersion',confirmation_version_value));SELECT * INTO replay FROM public.canonical_external_project_outcome_observations WHERE organization_id=org AND actor_user_id=actor AND request_key_hash=key_hash;IF FOUND THEN IF rtrim(replay.request_digest)<>request_hash THEN RAISE EXCEPTION 'Project outcome observation key conflict' USING ERRCODE='23505';END IF;SELECT * INTO consent_value FROM public.canonical_external_project_outcome_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1;source_current:=public.canonical_external_business_source_consent_basis(org,'project_change_order',source_value);basis:=public.canonical_external_project_outcome_basis(org,source_value,replay.estimate_id,replay.project_reference);RETURN jsonb_build_object('observation',public.canonical_external_project_outcome_projection(replay,basis,consent_value,source_current),'replayed',TRUE);END IF;SELECT * INTO consent_value FROM public.canonical_external_project_outcome_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1;source_current:=public.canonical_external_business_source_consent_basis(org,'project_change_order',source_value);IF consent_value.id IS NULL OR consent_value.action<>'grant' OR source_current IS NULL OR consent_value.source_consent_id<>(source_current->>'id')::uuid OR consent_value.source_consent_revision<>(source_current->>'revision')::bigint OR rtrim(consent_value.source_consent_digest)<>source_current->>'digest' THEN RAISE EXCEPTION 'Current source and project outcome permissions required' USING ERRCODE='P0002',CONSTRAINT='project_outcome_consent_unavailable';END IF;IF consent_value.revision<>expected_consent_revision OR rtrim(consent_value.canonical_digest)<>expected_consent_digest THEN RAISE EXCEPTION 'Project outcome permission changed' USING ERRCODE='40001';END IF;basis:=public.canonical_external_project_outcome_basis(org,source_value,estimate_value,project_reference_value);IF basis IS NULL THEN RAISE EXCEPTION 'Current reviewed project links and evidence required' USING ERRCODE='P0002',CONSTRAINT='project_outcome_lineage_unavailable';END IF;SELECT * INTO current_row FROM public.canonical_external_project_outcome_observations WHERE organization_id=org AND source_key=source_value AND estimate_id=estimate_value AND project_reference=project_reference_value ORDER BY revision DESC LIMIT 1 FOR UPDATE;IF current_row.id IS NOT NULL AND current_row.consent_id=consent_value.id AND current_row.source_digest=basis->>'sourceDigest' THEN RAISE EXCEPTION 'Current project outcome already recorded' USING ERRCODE='22023',CONSTRAINT='project_outcome_already_current';END IF;next_revision:=COALESCE(current_row.revision,0)+1;digest_value:=public.canonical_completion_digest(jsonb_build_object('organizationId',org,'sourceKey',source_value,'estimateId',estimate_value,'projectReference',project_reference_value,'revision',next_revision,'previousId',current_row.id,'consentId',consent_value.id,'consentRevision',consent_value.revision,'consentDigest',rtrim(consent_value.canonical_digest),'projectMatchId',basis->>'projectMatchId','projectMatchRevision',(basis->>'projectMatchRevision')::bigint,'projectMatchDigest',basis->>'projectMatchDigest','targetDigest',basis->>'targetDigest','sourceManifest',basis->'sourceManifest','changeOrderMatches',basis->'changeOrderMatches','sourceDigest',basis->>'sourceDigest','outcomes',basis->'outcomes','actorUserId',actor,'confirmationVersion',confirmation_version_value,'calculationVersion','m25-external-project-outcome-v1','requestDigest',request_hash));INSERT INTO public.canonical_external_project_outcome_observations(organization_id,source_key,estimate_id,project_reference,revision,previous_id,consent_id,consent_revision,consent_digest,project_match_id,project_match_revision,project_match_digest,target_digest,source_manifest,change_order_matches,source_digest,outcomes,actor_user_id,membership_id,auth_session_id,reason,confirmed,confirmation_version,calculation_version,request_key_hash,request_digest,canonical_digest)VALUES(org,source_value,estimate_value,project_reference_value,next_revision,current_row.id,consent_value.id,consent_value.revision,rtrim(consent_value.canonical_digest),(basis->>'projectMatchId')::uuid,(basis->>'projectMatchRevision')::bigint,basis->>'projectMatchDigest',basis->>'targetDigest',basis->'sourceManifest',basis->'changeOrderMatches',basis->>'sourceDigest',basis->'outcomes',actor,(authority->>'membershipId')::uuid,session_value,reason_value,TRUE,confirmation_version_value,'m25-external-project-outcome-v1',key_hash,request_hash,digest_value)RETURNING * INTO inserted;RETURN jsonb_build_object('observation',public.canonical_external_project_outcome_projection(inserted,basis,consent_value,source_current),'replayed',FALSE);END $$;

CREATE FUNCTION public.canonical_external_project_outcome_read(org UUID,actor UUID,role_value TEXT,session_value UUID,source_value TEXT,estimate_value UUID,project_reference_value TEXT) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ DECLARE consent_value public.canonical_external_project_outcome_consents%ROWTYPE;current_row public.canonical_external_project_outcome_observations%ROWTYPE;source_current JSONB;basis JSONB;history JSONB;total BIGINT;active_value BOOLEAN;BEGIN IF role_value IS NULL OR role_value NOT IN ('owner','admin') THEN RAISE EXCEPTION 'Project outcome learning restricted' USING ERRCODE='42501';END IF;PERFORM public.canonical_field_execution_actor_authority(org,actor,role_value,session_value,NULL,FALSE);IF source_value IS NULL OR source_value!~'^[a-z0-9][a-z0-9._-]{1,63}$' OR project_reference_value IS NULL OR length(project_reference_value) NOT BETWEEN 1 AND 128 OR project_reference_value!~'^[!-~]+$' THEN RAISE EXCEPTION 'Project outcome read invalid' USING ERRCODE='22023';END IF;SELECT * INTO consent_value FROM public.canonical_external_project_outcome_consents WHERE organization_id=org AND source_key=source_value ORDER BY revision DESC LIMIT 1;source_current:=public.canonical_external_business_source_consent_basis(org,'project_change_order',source_value);active_value:=COALESCE(consent_value.id IS NOT NULL AND consent_value.action='grant' AND source_current->>'id'=consent_value.source_consent_id::text AND source_current->>'digest'=rtrim(consent_value.source_consent_digest),FALSE);IF NOT active_value THEN RETURN jsonb_build_object('sourceKey',source_value,'activeConsent',FALSE,'current',NULL,'history','[]'::jsonb,'total',0,'truncated',FALSE,'consumptionBoundary','Project outcome advice is unavailable until permission is granted for the current project source.');END IF;basis:=public.canonical_external_project_outcome_basis(org,source_value,estimate_value,project_reference_value);SELECT * INTO current_row FROM public.canonical_external_project_outcome_observations WHERE organization_id=org AND source_key=source_value AND estimate_id=estimate_value AND project_reference=project_reference_value ORDER BY revision DESC LIMIT 1;SELECT count(*) INTO total FROM public.canonical_external_project_outcome_observations WHERE organization_id=org AND source_key=source_value AND estimate_id=estimate_value AND project_reference=project_reference_value;SELECT COALESCE(jsonb_agg(public.canonical_external_project_outcome_projection(x,basis,consent_value,source_current)ORDER BY revision DESC),'[]'::jsonb) INTO history FROM(SELECT * FROM public.canonical_external_project_outcome_observations WHERE organization_id=org AND source_key=source_value AND estimate_id=estimate_value AND project_reference=project_reference_value ORDER BY revision DESC LIMIT 20)x;RETURN jsonb_build_object('sourceKey',source_value,'activeConsent',TRUE,'current',CASE WHEN current_row.id IS NULL THEN NULL ELSE public.canonical_external_project_outcome_projection(current_row,basis,consent_value,source_current)END,'history',history,'total',total,'truncated',total>20,'consumptionBoundary','Recorded project outcomes are advisory. Contract movement is not automatically attributed to change orders.');END $$;

REVOKE ALL ON TABLE public.canonical_external_project_outcome_consents,public.canonical_external_project_outcome_observations FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_project_outcome_immutable() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_project_money_claim_valid(JSONB,BOOLEAN) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_project_outcomes_valid(JSONB) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_project_outcome_unavailable(TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_project_outcome_consent_projection(public.canonical_external_project_outcome_consents,JSONB) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_project_outcome_consent_guard() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_project_outcome_basis(UUID,TEXT,UUID,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_project_outcome_consent_read(UUID,UUID,TEXT,UUID,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_project_outcome_consent_mutate(UUID,UUID,TEXT,UUID,TEXT,TEXT,TEXT,JSONB) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_project_outcome_projection(public.canonical_external_project_outcome_observations,JSONB,public.canonical_external_project_outcome_consents,JSONB) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_project_outcome_observation_guard() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_project_outcome_observe(UUID,UUID,TEXT,UUID,TEXT,TEXT,TEXT,UUID,TEXT,BIGINT,TEXT,TEXT,BOOLEAN,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.canonical_external_project_outcome_read(UUID,UUID,TEXT,UUID,TEXT,UUID,TEXT) FROM PUBLIC;
